package com.zhibrary.auth;
import com.zhibrary.user.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="http://localhost:5173") public class AuthController { private final UserRepository users; public AuthController(UserRepository users){this.users=users;} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Map<String,String> p){String key=p.get("username"); User u=users.findByUsername(key).orElseGet(()->users.findByEmail(key).orElse(null)); if(u==null||!u.getPassword().equals(p.get("password")))return ResponseEntity.status(401).body(Map.of("message","Invalid credentials"));return ResponseEntity.ok(Map.of("username",u.getUsername(),"name",u.getFirstName()+" "+u.getLastName(),"role",u.getRole().name(),"fine",u.getOutstandingFine()));} @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Map<String,String> p){if(users.findByUsername(p.get("username")).isPresent()||users.findByEmail(p.get("email")).isPresent())return ResponseEntity.badRequest().body(Map.of("message","Username or email already exists"));User u=users.save(new User(p.get("firstName"),p.get("middleName"),p.get("lastName"),p.get("email"),p.get("username"),p.get("password"),UserRole.USER));return ResponseEntity.ok(Map.of("username",u.getUsername(),"role",u.getRole().name()));} }
